'use strict';
const KEY='alfaisal-review-studio-v1', $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const add=(d,n)=>{let v=new Date(d+'T12:00:00Z');v.setUTCDate(v.getUTCDate()+n);return v.toISOString().slice(0,10)}, fmt=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Riyadh'}):'Unscheduled', stamp=d=>new Date(d).toLocaleString('en-GB',{timeZone:'Asia/Riyadh',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
let saved={},view='dashboard',tab='all',editing=null, filters={q:'',course:'all',status:'all',due:'all'},storageOK=true;
try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={}}catch{storageOK=false}
let state=saved.records||{},day=today();$('#day').value=day;
const rec=x=>state[x.id]||{}, dates=x=>rec(x).dates||x.dates, title=x=>rec(x).title||x.title, done=(x,p)=>rec(x).done?.[p]||null, completed=x=>[0,1,2].filter(p=>done(x,p)).length;
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:1,records:state}));$('#storageStatus').textContent='';storageOK=true}catch{storageOK=false;$('#storageStatus').textContent='Saving unavailable. Export a backup before closing.'}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function tasks(items=DATA.items){return items.flatMap(x=>[0,1,2].map(p=>({x,p,date:dates(x)[p],done:done(x,p)})))}
function row(x){return `<article class="lecture ${x.course==='MOL'?'mol':''}"><div class="lecture-top"><span class="code">${esc(x.code)}</span><div class="lecture-info"><h3>${esc(title(x))}</h3><div class="meta">${esc(x.group)} ${x.midterm?' · Midterm coverage':''}<br>${x.course==='CVP'?'Preset PDF plan':'Suggested editable review plan'}${rec(x).dates?' · Dates customized':''}${rec(x).confidence?' · Confidence '+rec(x).confidence+'/5':''}</div></div><button class="edit" data-edit="${x.id}" aria-label="Edit ${esc(x.code)}">Edit ↗</button></div><div class="passes">${[0,1,2].map(p=>`<label class="pass ${done(x,p)?'done':dates(x)[p]<day?'late':''}"><input type="checkbox" data-id="${x.id}" data-pass="${p}" ${done(x,p)?'checked':''} aria-label="${esc(x.code)} ${p+1}${['st','nd','rd'][p]} review completed"><strong>${p+1}${['st','nd','rd'][p]} review</strong><small>${done(x,p)?'Done '+esc(stamp(done(x,p))):'Planned '+fmt(dates(x)[p])}</small></label>`).join('')}</div>${rec(x).notes?`<div class="note-preview">${esc(rec(x).notes)}</div>`:''}</article>`}
function progress(course){let a=DATA.items.filter(x=>x.course===course),t=tasks(a),n=t.filter(x=>x.done).length;return `<div class="progress-row"><div class="section-head"><strong>${course} ${course==='MOL'?'114':'112'}</strong><span>${Math.round(n/t.length*100)}%</span></div><div class="bar ${course==='MOL'?'mol':''}"><i style="width:${n/t.length*100}%"></i></div><small>${n} / ${t.length} reviews complete · ${a.filter(x=>completed(x)===3).length} / ${a.length} items fully reviewed</small></div>`}
function intro(label,heading,sub){return `<div class="intro"><div><div class="eyebrow muted">${label}</div><h1>${heading}</h1><p class="muted">${sub}</p></div><span class="pill">M1-A · GROUP 1.6</span></div>`}
function stats(){const t=tasks(),m=t.filter(t=>t.x.midterm),d=t.filter(t=>t.date===day&&!t.done),over=t.filter(t=>t.date<day&&!t.done);return `<div class="stats">${[['DUE ON '+fmt(day).toUpperCase(),d.length,'reviews still to do'],['MOL MIDTERM',m.filter(t=>!t.done).length,'of 39 review passes remaining'],['CVP PLAN',t.filter(t=>t.x.course==='CVP'&&!t.done).length,'of 153 review passes remaining'],['ALL REVIEWS',t.filter(t=>t.done).length+' / '+t.length,over.length+' overdue before selected day']].map(s=>`<div class="stat"><div class="eyebrow">${s[0]}</div><div class="value">${s[1]}</div><small>${s[2]}</small></div>`).join('')}</div>`}
function dashboard(){let diff=Math.round((new Date('2026-10-29T12:00:00Z')-new Date(day+'T12:00:00Z'))/86400000);let a=[...DATA.items].sort((a,b)=>(b.midterm?1:0)-(a.midterm?1:0)).filter(x=>dates(x).some((d,p)=>d===day&&!done(x,p))&&(tab==='all'||x.course===tab));return intro('A LITTLE STRUCTURE. A CLEAR NEXT STEP.','Make every review count.','Your MOL midterm comes first. Your CVP plan stays in view.')+`<section class="hero"><div><span class="pill">${diff>0?'UP NEXT · THURSDAY 29 OCT':diff===0?'EXAM DAY · THURSDAY 29 OCT':'MIDTERM · 29 OCT 2026'}</span><h2>Molecular Medicine midterm</h2><p>MOL 1–13 &nbsp; · &nbsp; 50 MCQs &nbsp; · &nbsp; 20% of course grade</p><button data-midterm>Open midterm review list ↗</button></div><div class="countdown"><strong>${diff>=0?diff:Math.abs(diff)}</strong><span>${diff>=0?'days to go':'days since exam'}<br>from planning day</span></div></section>`+stats()+`<div class="grid"><section class="panel"><div class="section-head"><h2>Your reviews for ${fmt(day)}</h2><button class="linkbtn" data-view="calendar">View schedule ↗</button></div><p class="section-sub">Check a pass only after you finish. Each pass saves its own timestamp.</p><div class="tabs">${[['all','All courses'],['MOL','MOL 114'],['CVP','CVP 112']].map(([id,t])=>`<button data-tab="${id}" class="${tab===id?'selected':''}">${t}</button>`).join('')}</div>${a.length?a.map(row).join(''):'<div class="empty">No unfinished reviews planned for this day.<br>Open All lectures to review or reschedule any item.</div>'}</section><div class="right-column"><section class="panel"><h2>Your progress</h2>${progress('MOL')}${progress('CVP')}<p class="section-sub">Planned reviews: 237. Initially completed: 0.</p></section><section class="panel"><div class="section-head"><h2>Midterm sprint</h2><span class="pill mol">SUGGESTED</span></div>${[['25 Oct','MOL 1–4 · first pass','Water, nucleic acids, replication, transcription I.'],['26 Oct','MOL 5–8 · first pass','Recall MOL 1–4. Continue through amino acids.'],['27 Oct','MOL 9–13 · first pass','Recall MOL 5–8. Finish all midterm topics.'],['28 Oct','Recall + mixed MCQs','Second pass MOL 9–13, third pass MOL 1–13. Triage weak areas and protect sleep.']].map(([d,t,s])=>`<div class="dayplan"><strong>${d} · ${t}</strong><p class="muted">${s}</p></div>`).join('')}<p class="notice">An intensive, editable catch-up plan. Adjust it to your starting point. The CVP PDF dates are preserved, including exam day reviews.</p></section><section class="panel"><h3>CVP stays on track</h3><p class="muted" style="font-size:12px">51 scheduled items · 3 passes each<br>25 Oct–14 Nov review passes<br>15–17 Nov mixed MCQs<br>18 Nov final / brief recall</p><button class="linkbtn" data-cvp>View complete CVP plan ↗</button></section></div></div>`}
function filtered(){return DATA.items.filter(x=>{let t=tasks([x]),c=completed(x);return (filters.course==='all'||x.course===filters.course||filters.course==='midterm'&&x.midterm)&&(!filters.q||(title(x)+' '+x.code+' '+x.group+' '+(rec(x).notes||'')).toLowerCase().includes(filters.q.toLowerCase()))&&(filters.status==='all'||filters.status==='notstarted'&&c===0||filters.status==='progress'&&c>0&&c<3||filters.status==='done'&&c===3||filters.status==='weak'&&((+rec(x).confidence>0&&+rec(x).confidence<=2)||rec(x).notes))&&(filters.due==='all'||t.some(t=>!t.done&&(filters.due==='today'?t.date===day:filters.due==='overdue'?t.date<day:t.date>=day&&t.date<=add(day,6))))})}
function lectures(){return intro('YOUR COMPLETE REVIEW LIBRARY',view==='weakness'?'Turn weak spots into strengths.':'One lecture. Three independent passes.',view==='weakness'?'Lectures with notes or confidence rated 1–2. Edit a lecture to assess it.':'CVP preset dates and suggested MOL reviews, together in one place.')+`<section class="panel"><div class="filters"><input id="search" type="search" placeholder="Search lectures, topics or notes…" value="${esc(filters.q)}" aria-label="Search lectures"><select id="course" aria-label="Filter by course">${[['all','All courses'],['MOL','MOL 114'],['CVP','CVP 112'],['midterm','MOL midterm · 1–13']].map(([v,l])=>`<option value="${v}" ${filters.course===v?'selected':''}>${l}</option>`).join('')}</select><select id="status" aria-label="Filter by status">${[['all','Any status'],['notstarted','Not started'],['progress','In progress'],['done','All 3 complete'],['weak','Weak areas / notes']].map(([v,l])=>`<option value="${v}" ${filters.status===v?'selected':''}>${l}</option>`).join('')}</select><select id="due" aria-label="Filter by due date">${[['all','Any due date'],['today','Due selected day'],['overdue','Overdue'],['week','Next 7 days']].map(([v,l])=>`<option value="${v}" ${filters.due===v?'selected':''}>${l}</option>`).join('')}</select></div><div id="results"></div></section>`}
function results(){let a=filtered();$('#results').innerHTML=`<p class="section-sub">${a.length} items · ${tasks(a).filter(t=>!t.done).length} unfinished passes</p>`+(a.length?a.map(row).join(''):'<div class="empty">No lectures match these filters.</div>')}
function calendar(){let start=add(day,-new Date(day+'T12:00:00Z').getUTCDay()),ev=DATA.events.filter(e=>e.date===day),a=DATA.items.filter(x=>dates(x).includes(day));return intro('STUDY & CAMPUS, SIDE BY SIDE','Your daily schedule.','Review due dates and documented teaching events remain distinct.')+`<div class="calendar-strip">${Array.from({length:7},(_,n)=>{let d=add(start,n);return `<button data-day="${d}" class="${day===d?'selected':''}">${['SUN','MON','TUE','WED','THU','FRI','SAT'][n]}<strong>${+d.slice(8)}</strong><small>${tasks().filter(t=>t.date===d&&!t.done).length} reviews due</small></button>`}).join('')}</div><div class="section-head"><button data-day="${add(day,-7)}">← Previous week</button><span>${fmt(start)} – ${fmt(add(start,6))}</span><button data-day="${add(day,7)}">Next week →</button></div><div class="grid"><section class="panel"><h2>Planned reviews · ${fmt(day)}</h2><p class="muted" style="font-size:11px">${tasks().filter(t=>t.date===day&&!t.done).length} unfinished passes. Other pass dates are shown for context.</p>${a.length?a.map(row).join(''):'<div class="empty">No reviews planned on this day.</div>'}</section><section class="panel"><h2>Course timetable & events</h2><p class="section-sub" style="margin-top:12px">Male-I lectures and M1-A labs. Exact group ranges override section defaults.</p>${ev.length?ev.map(e=>`<div class="event"><span class="pill">${esc(e.type)}</span><p><strong>${esc(e.title)}</strong></p>${e.slot?`<p>Source slot: ${esc(e.slot)}</p>`:''}${e.detail?`<p>${esc(e.detail)}</p>`:''}<small>${esc(e.source)}${e.cell?' · Sheet1!'+e.cell:''}</small></div>`).join(''):'<p class="muted">No documented events in the supplied files for this day.</p>'}<p class="notice">Timetable slot labels are reproduced as printed, not inferred event durations. Shared merged cells are included. Verify updated rooms and attendance details on Moodle.</p></section></div>`}
function methods(){return intro('GIVE EACH PASS A PURPOSE','Study. Recall. Consolidate.','The CVP PDF’s three-pass methods are preserved below. You can use them for MOL too.')+`<div class="threecol">${[['01','First study','Seniors video + slides + MCQs','Build your understanding. Use the slides as the source of truth and record the mechanisms or diagrams that need another look.'],['02','Second study','Written recall + MCQs','Close the slides and write what you remember. Check the gaps, then work through questions and add errors to your notes.'],['03','Third study','Rapid recall + mixed MCQs','Recall the core facts and mechanisms quickly. Mix topics and return to weak areas before you mark the pass done.']].map(([n,t,m,p])=>`<section class="method"><strong>${n}</strong><h2>${t}</h2><p><b>${m}</b></p><p class="muted">${p}</p></section>`).join('')}</div><section class="panel" style="margin-top:20px"><h2>A useful confidence check</h2><p class="muted">Rate each lecture from 1 (needs work) to 5 (exam ready) in Edit. Notes and ratings 1–2 appear in Weak areas. Confidence never completes a pass.</p><p>Before the MOL midterm: cover all of MOL 1–13. The guide does not give a per-lecture MCQ allocation. MOL 14–19 belong to TBL 2 and are outside midterm coverage.</p></section>`}
function sources(){return intro('FIVE FILES, ONE CLEAR PLAN','Know where each date comes from.','Original source dates are retained separately from your personal edits.')+`<section class="panel"><h2>Source register</h2><ol class="sources-list">${DATA.sources.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>The CVP PDF provides all 51 scheduled items and 153 review dates, October 25–November 14. Its closing plan continues through November 18. It is a study plan; teaching dates come from the XLSX.</p><p>The CVP syllabus provides objectives and assessment weights: TBL/PBL 5%, final MCQs 65%, SAQs 15%, OSPE 15%; no midterm. The timetable lists the final on November 18 and OSPE on November 19.</p><p>The MOL syllabus provides lecture objectives and practical coverage. The lecture/TBL/assessment guide provides lecture date ranges, TBL grouping, and exam coverage. Guide wording is retained for lecture titles; some syllabus titles differ slightly.</p><div class="notice">All MOL review due dates are suggestions generated for this tracker. October 25–28 is an intensive midterm catch-up plan. Later reviews are suggested after the documented lecture date, with 2- and 5-day follow-ups. Review Sessions I and II are included as items. No progress is pre-completed.</div></section><div class="threecol"><section class="panel"><h3>MOL midterm</h3><p>Thursday, 29 October 2026<br>50 MCQs · MOL 1–13<br>20% of course grade</p><p class="muted">No per-lecture question allocation is supplied. The timetable prints an 8:00 slot; the dashboard does not infer exam duration.</p></section><section class="panel"><h3>TBL grouping</h3><p>TBL 1 · MOL 1–7 · Sep 22<br>TBL 2 · MOL 14–19 · Nov 3<br>TBL 3 · MOL 20–24 · Nov 24</p><p class="muted">Guide/syllabus TBL times: 08:00–10:00. MOL 8–13 and 25–28 are outside TBL groups.</p></section><section class="panel"><h3>MOL final</h3><p>20 December 2026<br>90 MCQs + 5 SAQs</p><p class="muted">MCQs: all lectures + laboratory material. SAQs: all lectures. Labs: safety/instruments and DNA isolation/quantitation. Lab review dates are not supplied or invented.</p></section></div><section class="panel"><h2>Timetable interpretation</h2><p>Male-I column is used for lectures. M1-A anatomy lab slots are included; M1-B entries and physiology groups 1.1–1.3 are excluded. The November 9 physiology session explicitly says M1A 1.4–1.6 and is included. Shared sessions are read from horizontally merged cells.</p><p class="muted">The XLSX has repeated formatting far beyond its actual 25-column timetable. The parser uses the real weekly grids. MOL group-specific lab allocations not explicitly matching Group 1.6 are not assigned. Timetable row labels are displayed as source slots rather than inferred attendance durations.</p><details><summary>CVP syllabus content and objectives</summary><div class="syllabus">${DATA.cvpSyllabus.map(r=>`<p>${esc([...new Set(r)].join(' · '))}</p>`).join('')}</div></details></section><section class="panel"><h2>Your data</h2><p>Progress, notes, confidence, custom titles and dates are stored in this browser. Export a JSON backup to move devices or keep a safe copy. Import validates the backup before replacing saved progress. Original CVP dates remain available in every Edit dialog.</p></section>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=({dashboard,lectures,weakness:lectures,calendar,methods,sources}[view])();if(view==='lectures'||view==='weakness')results();}
function go(v){view=v;if(v==='weakness')filters.status='weak';else if(v==='lectures'&&filters.status==='weak')filters.status='all';location.hash=v;render()}
function openEdit(id){editing=DATA.items.find(x=>x.id===id);let x=editing;$('#editTitle').textContent=x.code+' · Review details';$('#editSource').textContent=x.source+' · '+(x.course==='CVP'?'Preset PDF dates retained below.':'All review due dates are suggested and editable.');$('#titleInput').value=title(x);$('#dateFields').innerHTML=[0,1,2].map(p=>`<label>${p+1}${['st','nd','rd'][p]} review<input type="date" id="date${p}" required value="${esc(dates(x)[p])}"><small>Original ${x.course==='CVP'?'PDF':'suggested'}: ${fmt(x.dates[p])}</small></label>`).join('');$('#confidence').value=rec(x).confidence||0;$('#notes').value=rec(x).notes||'';$('#objectives').textContent=(x.lectureDates?'Documented lecture date(s): '+x.lectureDates+'. ':'')+(x.objectives||x.group+'. See Sources & coverage for full CVP syllabus objectives.');$('#editor').showModal()}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view)go(b.dataset.view);if(b.hasAttribute('data-midterm')){filters={q:'',course:'midterm',status:'all',due:'all'};go('lectures')}if(b.hasAttribute('data-cvp')){filters={q:'',course:'CVP',status:'all',due:'all'};go('lectures')}if(b.dataset.tab){tab=b.dataset.tab;render()}if(b.dataset.edit)openEdit(b.dataset.edit);if(b.dataset.day){day=b.dataset.day;$('#day').value=day;render()}});
document.addEventListener('change',e=>{let t=e.target;if(t.matches('[data-pass]')){let id=t.dataset.id,p=+t.dataset.pass;state[id]={...state[id],done:{...state[id]?.done,[p]:t.checked?new Date().toISOString():null}};persist();render();toast(t.checked?'Review completed · timestamp saved':'Review completion cleared')}if(['course','status','due'].includes(t.id)){filters[t.id]=t.value;results()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.q=e.target.value;results()}});
$('#day').onchange=e=>{if(e.target.value){day=e.target.value;render()}};$('#today').onclick=()=>{day=today();$('#day').value=day;render()};$('#close').onclick=()=>$('#editor').close();$('#restore').onclick=()=>{editing.dates.forEach((d,p)=>$('#date'+p).value=d);toast('Preset dates restored in editor. Save to apply.')};$('#editform').onsubmit=e=>{e.preventDefault();state[editing.id]={...rec(editing),title:$('#titleInput').value.trim()||editing.title,dates:[0,1,2].map(p=>$('#date'+p).value),confidence:+$('#confidence').value,notes:$('#notes').value};persist();$('#editor').close();render();toast('Lecture updated')};
$('#export').onclick=()=>{let blob=new Blob([JSON.stringify({app:'alfaisal-review-studio',version:1,exportedAt:new Date().toISOString(),records:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='review-studio-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Backup exported')};$('#import').onclick=()=>$('#file').click();
function validateBackup(o){if(o?.app!=='alfaisal-review-studio'||o.version!==1||!o.records||Array.isArray(o.records)||typeof o.records!=='object')throw Error('This is not a Review Studio backup.');let clean={};for(let [id,r] of Object.entries(o.records)){if(!DATA.items.some(x=>x.id===id))throw Error('Unknown lecture in backup.');if(!r||typeof r!=='object'||Array.isArray(r))throw Error('Invalid lecture record.');let c={};if(r.title!==undefined){if(typeof r.title!=='string'||r.title.length>300)throw Error('Invalid title.');c.title=r.title}if(r.notes!==undefined){if(typeof r.notes!=='string'||r.notes.length>100000)throw Error('Invalid notes.');c.notes=r.notes}if(r.confidence!==undefined){if(!Number.isInteger(r.confidence)||r.confidence<0||r.confidence>5)throw Error('Invalid confidence.');c.confidence=r.confidence}if(r.dates!==undefined){if(!Array.isArray(r.dates)||r.dates.length!==3||r.dates.some(d=>typeof d!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d)||!Number.isFinite(Date.parse(d))||new Date(d).toISOString().slice(0,10)!==d))throw Error('Invalid review dates.');c.dates=r.dates}if(r.done!==undefined){if(!r.done||typeof r.done!=='object'||Array.isArray(r.done))throw Error('Invalid completion records.');c.done={};for(let [p,t] of Object.entries(r.done)){if(!['0','1','2'].includes(p)||t!==null&&(typeof t!=='string'||!Number.isFinite(Date.parse(t))))throw Error('Invalid completion timestamp.');c.done[p]=t}}clean[id]=c}return clean}
$('#file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>3000000)throw Error('Backup exceeds 3 MB.');let clean=validateBackup(JSON.parse(await f.text()));if(!confirm('Replace this browser’s saved progress with this backup? Export first if you need to keep your current progress.'))return;state=clean;persist();render();toast('Backup imported')}catch(err){alert('Import failed: '+err.message)}finally{e.target.value=''}};
window.addEventListener('hashchange',()=>{let v=location.hash.slice(1);if(['dashboard','lectures','calendar','weakness','methods','sources'].includes(v)&&view!==v){view=v;if(v==='weakness')filters.status='weak';render()}});window.addEventListener('storage',e=>{if(e.key===KEY)toast('Progress changed in another tab. Reload to use the latest copy.')});if(['dashboard','lectures','calendar','weakness','methods','sources'].includes(location.hash.slice(1)))view=location.hash.slice(1);if(view==='weakness')filters.status='weak';render();if(!storageOK)$('#storageStatus').textContent='Storage unavailable. Export before closing.';
